    # Mark all 0s connected to the grid boundary
    boundary_connected = set()
    queue = deque()

    # Add all 0s on the grid boundary to the queue
    for r in range(rows):
        for c in range(cols):
            if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                if grid[r][c] == 0:
                    queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        boundary_connected.add((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in boundary_connected:
                    queue.append((nr, nc))

    # Fill all non-boundary-connected 0s with 4
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in boundary_connected:
                result[r][c] = 4

    return result

